import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Cache for compiled report templates
    private final Map<String, String> templateCache = new HashMap<>();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Basic alphanumeric check on reportId (defense-in-depth)
        if (!reportId.matches("[a-zA-Z0-9_-]+")) {
            resp.sendError(400, "Invalid report id format");
            return;
        }

        try {
            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);

            // Fetch report metadata
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT title, template, owner FROM reports WHERE report_id = ?");
            metaStmt.setString(1, reportId);
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                conn.close();
                return;
            }

            String title = metaRs.getString("title");
            String template = metaRs.getString("template");

            // Build data query - filter parameter is concatenated for flexible reporting
            String dataQuery = "SELECT * FROM report_data WHERE report_id = '" + reportId + "'";
            if (filterExpr != null && !filterExpr.isEmpty()) {
                // Allow power users to add custom WHERE clauses for ad-hoc filtering
                dataQuery += " AND " + filterExpr;
            }

            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            // Build response
            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><head><title>" + title + "</title></head><body>");
            out.println("<h1>" + title + "</h1>");
            out.println("<table border='1'>");

            ResultSetMetaData rsmd = dataRs.getMetaData();
            int cols = rsmd.getColumnCount();
            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + rsmd.getColumnName(i) + "</th>");
            }
            out.println("</tr>");

            while (dataRs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + dataRs.getString(i) + "</td>");
                }
                out.println("</tr>");
            }

            out.println("</table></body></html>");

            dataRs.close();
            dataStmt.close();
            metaRs.close();
            metaStmt.close();
            conn.close();

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST endpoint for saving filter presets - not yet implemented
        resp.sendError(501, "Not implemented");
    }
}
